h=items['thm-sr-smooth-local-herglotz-noether'];st=h['statement'].replace('Conversely every future unit timelike Killing field','Conversely every future timelike Killing field').replace('n = z\' o sigma on U, a = z\'\' o sigma, and nabla n = dsigma (x) (z\'\' o sigma)',"n = z' o sigma on U, N(x)=1+eta(z''(sigma(x)),x-z(sigma(x)))>0, d sigma(v)=-eta(z'(sigma(x)),v)/N(x), a = (z'' o sigma)/N, and nabla n = dsigma (x) (z'' o sigma)")
